sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var status = 'bench_idea_innovation,bench_training,deployed,on_leave';
    if (event.payload.value.toString() == '') {
        api.setState('depStatusFilterParam', 'bench_idea_innovation,bench_training,deployed,on_leave');
        api.data.resource_profile_table.refresh();
    } else {
        api.setState('depStatusFilterParam', event.payload.value);
        api.data.resource_profile_table.refresh();
    }
}
